/**
 * Data access for the Pandas Mastery course. Loader only — every rule lives in
 * `core/learning/pcourse.ts`, and the artifact is generated by `scripts/pandas-course.cjs`.
 */
import { useEffect, useState } from 'react';
import type { NCourseFile } from '../learning/ncourse';

let cached: Promise<NCourseFile> | null = null;

function load(): Promise<NCourseFile> {
  if (!cached) {
    cached = fetch('generated/pandas-course/index.json')
      .then((r) => {
        if (!r.ok) throw new Error(`pandas-course/index.json: ${r.status}`);
        return r.json() as Promise<NCourseFile>;
      })
      .catch((error) => { cached = null; throw error; });
  }
  return cached;
}

export function usePandasCourse(): NCourseFile | null {
  const [data, setData] = useState<NCourseFile | null>(null);
  useEffect(() => {
    let live = true;
    load().then((d) => { if (live) setData(d); }).catch(() => { /* the page shows its loading state */ });
    return () => { live = false; };
  }, []);
  return data;
}
